package com.worksphere.controller; import com.worksphere.dto.job.*; import com.worksphere.service.JobService; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/jobs") public class JobController {private final JobService s;public JobController(JobService x){s=x;} @GetMapping public Object search(@RequestParam(required=false) String keyword,@RequestParam(required=false) String location,@RequestParam(required=false) String category,@RequestParam(required=false) String date,@RequestParam(required=false) Double minPay,@RequestParam(required=false) Double maxPay,@RequestParam(required=false) Boolean recommended,Authentication a){return s.search(new JobSearchFilter(keyword,location,category,date,minPay,maxPay,recommended),a);} @GetMapping("/my") public Object mine(Authentication a){return s.mine(a);} @GetMapping("/{id}") public JobResponse get(@PathVariable Long id,Authentication a){return s.get(id,a);} @GetMapping("/{jobId}/applications") public Object applicants(@PathVariable Long jobId,Authentication a,com.worksphere.service.ApplicationService x){return x.forJob(jobId,a);} @PostMapping public JobResponse create(Authentication a,@RequestBody JobRequest r){return s.create(a,r);} @PutMapping("/{id}") public JobResponse update(@PathVariable Long id,Authentication a,@RequestBody JobRequest r){return s.update(id,a,r);} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id,Authentication a){s.delete(id,a);return ResponseEntity.noContent().build();} }
